const flag = Symbol("flag");
const defaults = { lang: "en", theme: "dark" };
const prefs = Object.create(defaults);
prefs.theme = "light";
prefs[flag] = true;
Object.defineProperty(prefs, "version", { value: 2, enumerable: false });

const looped = [];
for (const key in prefs) looped.push(key);

console.log(looped.join(","));
console.log(Object.getOwnPropertyNames(prefs).join(","));
console.log(Reflect.ownKeys(prefs).length);
